#!/usr/bin/env python3
import sys, os, re, io, csv, gzip, json, codecs
import xml.etree.ElementTree as ET
from decimal import Decimal, ROUND_HALF_UP
from datetime import datetime, date, timedelta, timezone

FACT = {'kg': Decimal(1), 'g': Decimal('0.001'), 'lb': Decimal('0.45359237'),
        'oz': Decimal('0.028349523125')}
ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
COLS = {
    'east': ['id', 'type', 'shipped', 'gross', 'net', 'status', 'note'],
    'harbor': ['rec', 'ref', 'date', 'weight', 'state'],
    'lakeside': ['id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'],
    'river': ['t', 'ref', 'shipped', 'weight', 'status'],
    'west': ['id', 'typ', 'shipped', 'weight', 'status', 'note'],
}
DELIM = {'east': ',', 'lakeside': ',', 'harbor': '|', 'river': '\t', 'west': ';'}
HSTATE = {'DLV': 'delivered', 'DLL': 'delivered_late', 'CAN': 'cancelled',
          'RET': 'returned', 'HLD': 'held'}
FWSTATE = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned', 'H': 'held'}
MONTHS = {m: i + 1 for i, m in enumerate(
    ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'])}


def read_bytes(path):
    b = open(path, 'rb').read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    return b


def decode(b):
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8')
    if b[:2] == b'\xff\xfe':
        return b[2:].decode('utf-16-le')
    if b[:2] == b'\xfe\xff':
        return b[2:].decode('utf-16-be')
    enc = 'utf-8'
    head = b[:2000].decode('latin-1')
    m = re.search(r'^#\s*charset\s*:\s*([\w.\-]+)', head, re.M | re.I)
    if m:
        try:
            codecs.lookup(m.group(1))
            enc = m.group(1)
        except LookupError:
            pass
    return b.decode(enc)


def idnum(s):
    m = re.search(r'\d+', s or '')
    if not m or not re.match(r'\s*sh', s, re.I):
        return None
    return int(m.group())


def rtype(s):
    s = (s or '').strip().lower()
    if s.startswith('v'):
        return 'void'
    if s.startswith('c') or s.startswith('a'):
        return 'corr'
    return 'new'


def norm_status(s):
    s = (s or '').strip().lower().replace('-', '_').replace(' ', '_')
    return HSTATE.get(s.upper(), s)


def parse_weight(txt, decimal_comma):
    t = txt.strip()
    if decimal_comma:
        t = t.replace('.', '').replace(',', '.')
    else:
        t = t.replace(',', '')
    return Decimal(t)


def to_kg(val, unit):
    return val * FACT[unit]


def parse_date(v, form):
    """Return (year, month) of a UTC ship time."""
    v = v.strip()
    if re.search(r'\d[T ]\d', v) and re.match(r'\d{4}-\d\d-\d\d', v):
        dt = datetime.fromisoformat(v.replace(' ', 'T', 1))
        if dt.tzinfo is not None:
            dt = dt.astimezone(timezone.utc)
        return dt.year, dt.month
    f = (form or '').strip().upper()
    if f == 'SERIAL' or (not f and re.fullmatch(r'\d{5}(\.\d+)?', v)):
        d = date(1899, 12, 30) + timedelta(days=int(float(v)))
        return d.year, d.month
    m = re.fullmatch(r'(\d{1,2})\s+([A-Za-z]{3})[a-z]*\s+(\d{4})', v)
    if m:
        return int(m.group(3)), MONTHS[m.group(2).lower()]
    p = [int(x) for x in re.findall(r'\d+', v)]
    if len(p) != 3:
        raise ValueError(v)
    if f in ('DMY', 'DD/MM/YYYY', 'DD.MM.YYYY'):
        return p[2], p[1]
    if f == 'MM/DD/YYYY':
        return p[2], p[0]
    if f in ('ISO', 'YMD', 'YYYY-MM-DD') or p[0] > 31:
        return p[0], p[1]
    if '.' in v:
        return p[2], p[1]
    return p[2], p[1]


def split_records(text, delim):
    """Yield ('comment', line) or ('row', fields) honouring CSV quoting."""
    lines = text.replace('\r\n', '\n').split('\n')
    i = 0
    quoted = delim == ','
    while i < len(lines):
        ln = lines[i]
        i += 1
        if not ln.strip():
            continue
        if ln.startswith('#'):
            yield 'comment', ln
            continue
        if quoted:
            acc = ln
            while acc.count('"') % 2 and i < len(lines):
                acc += '\n' + lines[i]
                i += 1
            row = next(csv.reader(io.StringIO(acc, newline=''), delimiter=','))
            yield 'row', row
        else:
            yield 'row', ln.split(delim)


def parse_delimited(depot, text):
    delim = DELIM[depot]
    cols = COLS[depot]
    seq = None
    dirs = {}
    hdr = None
    recs = []
    for kind, x in split_records(text, delim):
        if kind == 'comment':
            m = re.match(r'#\s*([^:=]+?)\s*:\s*(.*)$', x)
            if m:
                dirs[m.group(1).strip().lower()] = m.group(2).strip()
                if m.group(1).strip().lower() == 'seq':
                    seq = int(m.group(2))
            else:
                m = re.search(r'seq=(\d+)', x)
                if m and seq is None:
                    seq = int(m.group(1))
            continue
        row = [f.strip() if delim != ',' else f for f in x]
        if all(f.strip() in cols for f in row) and row:
            hdr = [f.strip() for f in row]
            continue
        if hdr is None:
            continue
        wcol = next((c for c in ('gross', 'weight', 'gross_kg') if c in hdr), None)
        own_unit = None
        if len(row) == len(hdr) + 1 and wcol:
            wi = hdr.index(wcol)
            if row[wi + 1].strip().lower() in FACT:
                own_unit = row[wi + 1].strip().lower()
                del row[wi + 1]
        if len(row) != len(hdr):
            continue
        d = dict(zip(hdr, row))
        idf = d.get('id') or d.get('ref') or ''
        n = idnum(idf)
        if n is None:
            continue
        typ = rtype(d.get('type') or d.get('kind') or d.get('typ') or d.get('t') or d.get('rec'))
        if typ == 'void':
            recs.append((n, 'void', None))
            continue
        form = dirs.get('dates') or dirs.get('date format')
        shipped = d.get('shipped') or d.get('date')
        ym = parse_date(shipped, form)
        wtxt = d[wcol].strip()
        unit = None
        m = re.fullmatch(r'(.*?)\s*([A-Za-z]+)', wtxt)
        if m and m.group(2).lower() in FACT:
            wtxt, unit = m.group(1), m.group(2).lower()
        if unit is None and wcol.endswith('_kg'):
            unit = 'kg'
        if unit is None:
            unit = own_unit
        if unit is None:
            u = dirs.get('unit') or dirs.get('weight unit')
            if u:
                u = u.split()[0].lower()
                if u in FACT:
                    unit = u
        if unit is None:
            unit = 'kg'
        w = to_kg(parse_weight(wtxt, depot == 'west'), unit)
        st = norm_status(d.get('status') or d.get('state'))
        recs.append((n, typ, (ym, w, st)))
    return seq, recs


def parse_south(text):
    seq = None
    layout = None
    recs = []
    LEN = {'FW1': 42, 'FW2': 43, 'FW3': 41}
    for ln in text.replace('\r\n', '\n').split('\n'):
        if not ln.strip() or '\x0c' in ln:
            continue
        if ln.startswith('#'):
            m = re.match(r'#LAYOUT\s+(\w+)', ln)
            if m:
                layout = m.group(1)
            m = re.match(r'#SEQ\s+(\d+)', ln)
            if m:
                seq = int(m.group(1))
            continue
        lay = layout
        if LEN.get(lay) != len(ln):
            lay = next((k for k, v in LEN.items() if v == len(ln)), None)
            if lay is None:
                continue
        if lay == 'FW1':
            id_, t, sh, w, st = ln[0:9], ln[9], ln[10:17], ln[17:25], ln[25]
            unit, mult = 'g', Decimal(1)
        elif lay == 'FW2':
            t, id_, sh, w, st = ln[0], ln[1:10], ln[10:18], ln[18:26], ln[26]
            unit, mult = 'kg', Decimal('0.01')
        else:
            id_, sh, t, w, st = ln[0:9], ln[9:16], ln[16], ln[17:24], ln[24]
            unit, mult = 'lb', Decimal('0.1')
        n = idnum(id_)
        if n is None:
            continue
        typ = rtype(t)
        if typ == 'void':
            recs.append((n, 'void', None))
            continue
        if lay == ...:
            pass
        if len(sh.strip()) == 7:
            d = date(int(sh[:4]), 1, 1) + timedelta(days=int(sh[4:]) - 1)
        else:
            d = date(int(sh[:4]), int(sh[4:6]), int(sh[6:8]))
        kg = to_kg(Decimal(int(w)) * mult, unit)
        recs.append((n, typ, ((d.year, d.month), kg, FWSTATE.get(st.strip().upper(), st.strip().lower()))))
    return seq, recs


def parse_north(text):
    seq = None
    recs = []
    for ln in text.replace('\r\n', '\n').split('\n'):
        if not ln.strip():
            continue
        v = json.loads(ln, parse_float=Decimal, parse_int=Decimal)
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if 'meta' in o and isinstance(o['meta'], dict):
                if 'seq' in o['meta']:
                    seq = int(o['meta']['seq'])
                continue
            n = idnum(str(o.get('id', '')))
            if n is None:
                continue
            typ = rtype(o.get('kind'))
            if typ == 'void':
                recs.append((n, 'void', None))
                continue
            wk = next(k for k in o if k.startswith('weight_'))
            unit = wk[7:].lower()
            w = to_kg(Decimal(str(o[wk])), unit)
            recs.append((n, typ, (parse_date(o['shipped_at'], 'iso'), w, norm_status(o.get('status')))))
    return seq, recs


def parse_central(b):
    root = ET.fromstring(b)
    seq = int(root.get('seq'))
    ru = (root.get('weight-unit') or 'kg').lower()
    recs = []
    for s in root.iter('shipment'):
        n = idnum(s.get('id'))
        if n is None:
            continue
        typ = rtype(s.get('type'))
        if typ == 'void':
            recs.append((n, 'void', None))
            continue
        sh = s.get('shipped')
        if sh is None:
            sh = s.findtext('shipped')
        we = s.find('weight')
        unit = (we.get('unit') or ru).lower()
        w = to_kg(Decimal(we.text.strip().replace(',', '')), unit)
        recs.append((n, typ, (parse_date(sh, None), w, norm_status(s.findtext('status')))))
    return seq, recs


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if not os.path.isfile(p):
            continue
        depot = name.split('-')[0]
        exports.setdefault(depot, [])
        b = read_bytes(p)
        if depot == 'central':
            seq, recs = parse_central(b)
        elif depot == 'south':
            seq, recs = parse_south(decode(b))
        elif depot == 'north':
            seq, recs = parse_north(decode(b))
        elif depot in DELIM:
            seq, recs = parse_delimited(depot, decode(b))
        else:
            continue
        exports[depot].append((seq if seq is not None else -1, name, recs))
    corrections = resends = 0
    current = {}
    for depot, lst in exports.items():
        cur = {}
        for seq, name, recs in sorted(lst, key=lambda e: (e[0], e[1])):
            for n, typ, rec in recs:
                if typ == 'new':
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = rec
                elif typ == 'corr':
                    cur[n] = rec
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur
    depots = {d: [0, Decimal(0)] for d in sorted(exports)}
    months = {}
    handovers = 0
    owners = {}
    for d in current:
        for n in current[d]:
            owners.setdefault(n, []).append(d)
    rank = {d: i for i, d in enumerate(ORDER)}
    for n, ds in owners.items():
        if len(ds) > 1:
            handovers += 1
        d = min(ds, key=lambda x: rank.get(x, 99))
        (y, m), w, st = current[d][n]
        if st not in ('delivered', 'delivered_late'):
            continue
        depots[d][0] += 1
        depots[d][1] += w
        k = '%04d-%02d' % (y, m)
        mo = months.setdefault(k, [0, Decimal(0)])
        mo[0] += 1
        mo[1] += w

    def r(x):
        return float(x.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    out = {
        'depots': {d: {'shipments': v[0], 'total_kg': r(v[1])} for d, v in depots.items()},
        'months': {k: {'shipments': months[k][0], 'total_kg': r(months[k][1])} for k in sorted(months)},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': handovers,
    }
    with open(out_file, 'w') as f:
        json.dump(out, f, indent=2)


main()
